(window.FREALLY_I18N = window.FREALLY_I18N || {})["vi"] = {"hero.headline":"<span class=\"hl-muted\">Xem đôi tay thật chơi nhạc của bạn.</span> <span class=\"cycle\" data-cycle=\"hero.cycle\" data-words=\"Then drag it into your DAW.|Read every note.|Learn how it is played.\">Rồi kéo nó vào DAW của bạn.</span>","hero.cycle":"Rồi kéo nó vào DAW của bạn.|Đọc từng nốt nhạc.|Học cách chơi nó.","hero.sub":"Hợp âm, một giai điệu, một dòng bass và một giai điệu đối, được viết theo bất kỳ phong cách nào, hiển thị thành bản nhạc và được đôi tay chân thực chơi trên những nhạc cụ chân thực, từ piano và guitar cho đến cả một ban nhạc. Kèm theo các bài học nhạc dạy bạn tự mình chơi, sáng tác và phối khí bản nhạc ấy. Ngoại tuyến và 100% không dùng AI.","hero.chipStandalone":"Ứng dụng độc lập","what.title":"Đây là gì","what.p1":"Phần lớn những người dùng trình tạo hợp âm chưa bao giờ thấy các phần nhạc của nó sẽ được chơi như thế nào, và phần lớn những người học một nhạc cụ chưa bao giờ được nhìn cận cảnh đôi tay của một người chơi. Handscore cho bạn thấy cả hai.","what.p2":"Chọn một thể loại, một nghệ sĩ hoặc một nhà sản xuất, và Handscore viết bốn phần nhạc theo phong cách đó: hợp âm, một giai điệu, một dòng bass và một giai điệu đối. Chúng hiện ra thành các tờ bản nhạc trên giá nhạc của nhạc cụ, và đôi tay chân thực chơi chúng theo cách một người chơi nhạc cụ đó sẽ chơi: mỗi ngón tay đặt trên đúng phím mà một nghệ sĩ piano sẽ dùng, mỗi ngăn phím và mỗi lần quạt dây đúng như một nghệ sĩ guitar sẽ làm. Các cây piano đến trước, tiếp theo là guitar và guitar bass, rồi sau đó là mọi họ nhạc cụ, cho đến cả một ban nhạc.","what.p3":"Mỗi nốt được hiển thị ngay tại nơi nó được chơi, mỗi phím piano ghi tên ở mặt trước, nên bạn thấy chính xác những gì đang vang lên. Khi một phần đã ưng ý, hãy kéo nó từ tờ nhạc của nó thẳng lên một track trong DAW của bạn.","what.p4":"Và nó còn dạy học. Các bài học bắt đầu từ ngày đầu tiên bên cây piano, lắng nghe bạn chơi và chuyển sang phần tiếp theo khi bạn đã chơi đúng, rồi tiếp tục với đọc bản nhạc, tiết tấu, luyện tai, nhạc lý, sáng tác ca khúc và viết lời, phối khí bài hát, mix và finger drumming.","inside.title":"Nó sẽ làm được gì","inside.instruments.title":"Mọi họ nhạc cụ","inside.instruments.body":"Bốn cây piano thật đi trước, tiếp đến là guitar và guitar bass; sau đó là organ, nhạc cụ gõ dùng dùi, đàn hạc, nhạc cụ dây kéo vĩ, kèn gỗ, kèn đồng và một bộ trống, cho đến cả một ban nhạc, mỗi lần một họ.","inside.hands.title":"Đôi tay chân thực","inside.hands.body":"Hai bàn tay chơi mọi nốt theo cách một người chơi nhạc cụ đó sẽ chơi: đúng ngón tay mà một nghệ sĩ piano sẽ chọn, đúng ngăn phím và cú gảy mà một nghệ sĩ guitar sẽ dùng.","inside.lessons.title":"Bài học âm nhạc","inside.lessons.body":"Các khóa học từ những nốt đầu tiên của bạn trên piano đến đọc bản nhạc, tiết tấu, luyện tai, nhạc lý, sáng tác ca khúc và viết lời, phối khí bài hát và mix. Chúng lắng nghe bạn chơi, và đọc từng bài học cho bạn nghe khi bạn bật công tắc Đọc to.","inside.drums.title":"Finger drumming","inside.drums.body":"Các mẫu trống được tạo ra hoặc do bạn tự chơi vào trên một bộ điều khiển pad có các pad sáng lên theo từng cú gõ, cùng một khóa học từ nhịp đầu tiên đến những groove hoàn chỉnh.","inside.sheets.title":"Bốn tờ bản nhạc","inside.sheets.body":"Hợp âm, giai điệu, giai điệu đối và bass, mỗi phần trên một tờ riêng, với mọi nốt sáng lên khi được chơi.","inside.styles.title":"Mọi phong cách mà Freally MIDI Master biết","inside.styles.body":"73 thể loại, 1.507 nghệ sĩ và 833 nhà sản xuất, từ cùng những bộ tạo dựa trên quy tắc.","inside.drag.title":"Kéo MIDI","inside.drag.body":"Từng phần một hoặc cả bốn cùng lúc, kéo từ các tờ nhạc thẳng vào DAW của bạn, hoặc lưu thành tệp MIDI hay thành PDF của các tờ nhạc.","inside.views.title":"Góc nhìn phía trước, từ trên xuống và từ bên cạnh","inside.views.body":"Chuyển giữa các góc nhìn trong khi nhạc đang phát; các tờ nhạc xoay theo để luôn dễ đọc và đôi tay không bao giờ bỏ lỡ một nốt nào.","inside.daw.title":"Trong mọi DAW","inside.daw.body":"CLAP, VST3 và AU, cùng một ứng dụng độc lập. Windows, macOS và Linux.","inside.offline.title":"Ngoại tuyến, không AI","inside.offline.body":"Không tài khoản, không đo lường từ xa, không mạng, không mô hình. Mọi phần nhạc, cách bấm ngón và chuyển động đều đến từ các quy tắc, được một cổng kiểm tra khi dựng bảo đảm chứ không chỉ là lời hứa.","ladder.title":"Con đường đến 1.0, và tiếp tới 2.0","ladder.intro":"Mỗi phiên bản một dòng. Các bài học, finger drumming, guitar và guitar bass đến trước 1.0. Sau đó, mỗi phiên bản mang đến một họ nhạc cụ mới, được đôi tay chân thực chơi theo cách một giáo viên sẽ chỉ cho bạn.","ladder.rung.v0.1.0":"Nền móng: plugin tải được dưới dạng CLAP, VST3 và AU lẫn ứng dụng độc lập, đề nghị bạn chấp nhận giấy phép, và mở ra một bàn phím 88 phím với tên của mọi phím.","ladder.rung.v0.2.0":"Những cây piano thật: đại dương cầm, piano cơ, piano đứng và honky-tonk, với các phím chuyển động và vang lên khi chơi.","ladder.rung.v0.3.0":"Đôi tay chân thực trên bàn phím, bấm ngón mọi nốt theo cách một nghệ sĩ piano sẽ làm, cùng sáu mươi hai bài kinh điển thuộc phạm vi công cộng để học và một thanh điều khiển phát để tua qua chúng trong khi vẫn nghe được.","ladder.rung.v0.4.0":"Tạo nhạc theo bất kỳ phong cách nào, đọc bốn tờ nhạc khi chúng sáng lên, và kéo MIDI vào DAW của bạn.","ladder.rung.v0.5.0":"Góc nhìn từ trên xuống và từ bên cạnh, với các tờ nhạc nằm phẳng trên đàn piano, và chuyển đổi liền mạch giữa các góc nhìn.","ladder.rung.lessons-1":"Học từ ngày đầu tiên: một khóa piano lắng nghe bạn chơi và chuyển sang phần tiếp theo khi bạn đã chơi đúng, cùng một công tắc Đọc to để đọc từng bài học cho bạn nghe, với từng chữ sáng lên khi được đọc tới.","ladder.rung.mixer":"Một mixer cho từng phần nhạc, với fader, pan, EQ, hiệu ứng và nén, và bản mix được giữ nguyên khi kéo ra.","ladder.rung.song-view":"Chế độ xem Bài hát: tự tay dựng cả một bài hát từ các đoạn, hoặc bắt đầu từ bản phối của một nghệ sĩ hay một thể loại, rồi xem bài hát được chơi và kéo nó vào DAW của bạn.","ladder.rung.lessons-2":"Thêm các khóa học: đọc bản nhạc, tiết tấu, luyện tai, nhạc lý với Nashville Number System, sáng tác ca khúc và viết lời, phối khí và mix.","ladder.rung.finger-drumming":"Finger drumming trên bộ điều khiển pad có các pad sáng lên theo từng cú gõ, từ nhịp đầu tiên đến những groove hoàn chỉnh.","ladder.rung.live-listening":"Nghe trực tiếp: chơi một nhạc cụ thật qua micro hoặc dây cáp nhạc cụ, và các bài học sẽ nghe thấy.","ladder.rung.guitars":"Các cây guitar: guitar thùng, guitar dây nylon, guitar điện và guitar chặn tiếng, với cách bấm phím, gảy dây và quạt dây thật.","ladder.rung.bass":"Guitar bass, chơi bằng ngón tay và bằng kỹ thuật slap.","ladder.rung.own-audio":"Âm thanh và MIDI của riêng bạn, được đọc thành các phần nhạc và được đôi tay chơi lại.","ladder.rung.classics":"Nhạc kinh điển: những giai điệu thuộc phạm vi công cộng để xem và nghe.","ladder.rung.realism":"Lượt trau chuốt độ chân thực: ánh sáng, chất liệu và chuyển động được đối chiếu với cảnh chơi đàn quay thật.","ladder.rung.finish":"Hoàn thiện: phần cài đặt, mười tám ngôn ngữ ở mọi nơi, khả năng tiếp cận và tài liệu hướng dẫn.","ladder.rung.v1.0.0-beta.1":"Thông báo cập nhật cùng các phiên bản dùng thử và trả phí.","ladder.rung.v1.0.0":"Bản phát hành công khai đầu tiên.","ladder.rung.v1.1.0":"Piano điện và organ, trong đó organ có bàn phím pedal để chơi dòng bass.","ladder.rung.v1.2.0":"Đàn harpsichord, clavinet, celesta và piano đồ chơi; ukulele, banjo và mandolin.","ladder.rung.v1.3.0":"Nhạc cụ gõ dùng dùi: xylophone, marimba, vibraphone và glockenspiel.","ladder.rung.v1.4.0":"Đàn hạc, koto, sitar và dulcimer núi.","ladder.rung.v1.5.0":"Violin, viola, cello và double bass, kéo vĩ và gảy dây.","ladder.rung.v1.6.0":"Sáo flute, clarinet, các loại saxophone, oboe và sáo recorder.","ladder.rung.v1.7.0":"Kèn trumpet, kèn trombone, kèn cor và kèn tuba.","ladder.rung.v1.8.0":"Một bộ trống được sắp đặt và chơi theo cách một tay trống chuyên nghiệp sẽ làm.","ladder.rung.v1.9.0":"Chơi theo và chế độ học.","ladder.rung.v2.0.0":"Ban nhạc: mỗi phần trên nhạc cụ riêng, mỗi nhạc cụ có người chơi riêng.","ladder.note":"Một phiên bản hoàn tất đã được dựng và gắn thẻ. Đó không phải là bản tải xuống: chưa có bản tải xuống nào trước 1.0.0.","honest.title":"Hiện giờ nó đang ở đâu","honest.start.title":"Nó đang ở những bước đầu tiên","honest.start.body":"Phiên bản 0.7.0 chạy trong DAW và mở ra với bốn cây đàn piano thật do đôi tay chân thực chơi, nhìn từ phía trước, từ trên xuống hoặc từ bên cạnh, máy quay lướt giữa các góc nhìn trong khi nhạc vẫn chơi. Tìm một thể loại, nghệ sĩ hoặc nhà sản xuất, nhấn Tạo, và bốn bè được viết theo phong cách đó, in thành bản nhạc trên giá nhạc của đàn và được đôi tay chơi — sẵn sàng để kéo vào DAW dưới dạng MIDI hoặc âm thanh, chỉnh từng nốt, hoặc xuất ra MIDI hay PDF. Mỗi bè phát qua kênh riêng trong một bàn trộn, có trình chỉnh sửa đường bao để tạo hình, và có thể chơi bằng một nhạc cụ của riêng bạn. Có sáu mươi hai bài cổ điển thuộc phạm vi công cộng để học, cùng thanh điều khiển phát để tạm dừng, tua lại và lướt qua bài hát, và một khóa piano 400 ngày dạy bạn chơi, lắng nghe khi bạn chơi. Mọi nhạc cụ khác và các khóa học mới sẽ đến qua từng phiên bản, như chiếc thang ở trên cho thấy.","honest.downloads.title":"Chưa có bản tải xuống nào trước 1.0.0","honest.downloads.body":"Không có bản beta trên trang này, không có bản dựng thử và không có quyền truy cập sớm.","honest.network.title":"Bản thân Handscore không bao giờ lên mạng","honest.network.body":"Plugin và ứng dụng độc lập không chứa mã mạng nào, và một cổng kiểm tra khi dựng sẽ thất bại nếu có mã như vậy được thêm vào. Nhạc cụ của riêng bạn mà bạn nạp vào một bè là của bạn: nó chạy trong tiến trình riêng và làm những gì nó vẫn luôn làm. Một phiên bản sau này có thể thêm một tính năng kiểm tra cập nhật, luôn tắt trừ khi bạn tự bật lên, được chạy bởi một chương trình riêng biệt.","site.tagline":"Xem đôi tay thật chơi nhạc của bạn. Rồi kéo nó vào DAW của bạn.","footer.licence":"Phần mềm độc quyền — Bảo lưu mọi quyền. © 2026 Mike Weaver, kinh doanh dưới tên Havoc Software. Không phải mã nguồn mở.","footer.yours":"MIDI bạn tạo ra và kéo vào DAW là của bạn. Tác giả của Handscore không nhận bất kỳ quyền sở hữu nào đối với nó.","featuresPage.lead":"Bốn phần nhạc được viết theo bất kỳ phong cách nào, hiển thị thành bản nhạc và được đôi tay chân thực chơi trên những nhạc cụ chân thực, mọi phần đều kéo thẳng được vào DAW của bạn, cùng các bài học nhạc dạy bạn tự mình chơi, sáng tác và phối khí bản nhạc ấy.","featuresPage.version":"Trang này mô tả những gì Freally Handscore phiên bản 1.0 sẽ làm. Phiên bản hiện tại là 0.7.0: xem con đường đến 1.0 ở trang chủ.","featuresPage.numbers.parts":"phần: hợp âm, giai điệu, giai điệu đối và bass","featuresPage.numbers.genres":"thể loại","featuresPage.numbers.artists":"nghệ sĩ","featuresPage.numbers.producers":"nhà sản xuất","featuresPage.numbers.keys":"phím, mỗi phím ghi tên ở mặt trước","featuresPage.numbers.plugins":"định dạng plugin, cùng một ứng dụng độc lập","featuresPage.numbers.languages":"ngôn ngữ","featuresPage.numbers.ai":"mô hình AI","featuresPage.free.title":"Miễn phí hôm nay","featuresPage.free.body":"Handscore hiện miễn phí: không có gói trả phí, không thuê bao và không tài khoản. Hiện chưa có gì để tải xuống, vì không có bản tải xuống nào trước phiên bản 1.0.0, và các phiên bản sau này có thể được bán.","featuresPage.cards.title":"Phiên bản 1.0 làm được gì","featuresPage.cards.pianos.title":"Bốn cây piano thật","featuresPage.cards.pianos.body":"Một cây đại dương cầm, một cây piano cơ, một cây piano đứng và một cây piano honky-tonk, mỗi cây có các phím chuyển động khi vang lên, và được chơi bằng cùng những giọng piano đã đo đạc như của Freally MIDI Master.","featuresPage.cards.strings.title":"Guitar và guitar bass","featuresPage.cards.strings.body":"Guitar thùng, guitar dây nylon, guitar điện và guitar chặn tiếng, với cách bấm phím, gảy dây và quạt dây thật, cùng guitar bass, chơi bằng ngón tay và bằng kỹ thuật slap.","featuresPage.cards.hands.title":"Đôi tay chân thực","featuresPage.cards.hands.body":"Hai bàn tay chơi mọi nốt theo cách một người chơi đàn sẽ chơi: đúng ngón tay mà một nghệ sĩ piano sẽ chọn, đúng ngăn phím và cú gảy mà một nghệ sĩ guitar sẽ dùng.","featuresPage.cards.sheets.title":"Bốn tờ bản nhạc","featuresPage.cards.sheets.body":"Hợp âm, giai điệu, giai điệu đối và bass, mỗi phần trên một tờ riêng, với mọi nốt sáng lên khi được chơi.","featuresPage.cards.styles.title":"Mọi phong cách mà Freally MIDI Master biết","featuresPage.cards.styles.body":"Chọn một trong 73 thể loại, 1.507 nghệ sĩ hoặc 833 nhà sản xuất, và cùng những bộ tạo dựa trên quy tắc sẽ viết bốn phần nhạc theo phong cách đó.","featuresPage.cards.yours.title":"Âm thanh và MIDI của riêng bạn","featuresPage.cards.yours.body":"Đưa vào âm thanh hoặc MIDI của riêng bạn, và Handscore sẽ đọc nó thành các phần nhạc để đôi tay chơi.","featuresPage.cards.classics.title":"Nhạc kinh điển","featuresPage.cards.classics.body":"Những bài hát thuộc phạm vi công cộng để học, từ bài hát thiếu nhi và thánh ca Giáng sinh đến quốc ca và các chủ đề cổ điển, mỗi bài được soạn cho hai tay và được đôi tay trên sân khấu chơi. Chỉ hợp âm của chúng mới có thể rời khỏi Handscore.","featuresPage.cards.lessons.title":"Bài học âm nhạc","featuresPage.cards.lessons.body":"Một khóa piano từ ngày đầu tiên, lắng nghe bạn chơi và chuyển sang phần tiếp theo khi bạn đã chơi đúng, rồi các khóa học về đọc bản nhạc, tiết tấu, luyện tai, nhạc lý, sáng tác ca khúc và viết lời, phối khí bài hát và mix. Bật công tắc Đọc to và từng bài học sẽ được đọc cho bạn nghe, với từng chữ sáng lên khi được đọc tới; các khóa học sau này nghe được nhạc cụ thật qua micro hoặc dây cáp.","featuresPage.cards.drums.title":"Finger drumming","featuresPage.cards.drums.body":"Một bộ điều khiển pad do đôi tay chân thực chơi, mỗi pad sáng lên khi được gõ. Tạo một mẫu trống hoặc tự chơi mẫu của riêng bạn vào, cho nó lặp lại và thêm vào đó, rồi học từ nhịp đầu tiên đến những groove hoàn chỉnh.","featuresPage.cards.songs.title":"Trọn bài hát và một mixer","featuresPage.cards.songs.body":"Tự tay dựng một bài hát từ các đoạn hoặc bắt đầu từ bản phối của một nghệ sĩ, rồi mix từng phần nhạc trên dải kênh riêng của nó, và kéo ra với bản mix được giữ nguyên.","featuresPage.cards.drag.title":"Kéo MIDI","featuresPage.cards.drag.body":"Từng phần một hoặc cả bốn cùng lúc, kéo từ các tờ nhạc thẳng vào DAW của bạn, hoặc lưu thành tệp MIDI hay thành PDF của các tờ nhạc.","featuresPage.cards.views.title":"Góc nhìn phía trước, từ trên xuống và từ bên cạnh","featuresPage.cards.views.body":"Chuyển giữa các góc nhìn trong khi nhạc đang phát; các tờ nhạc xoay theo để luôn dễ đọc và đôi tay không bao giờ bỏ lỡ một nốt nào.","featuresPage.cards.daw.title":"Trong mọi DAW","featuresPage.cards.daw.body":"CLAP và VST3 trên Windows, macOS và Linux, AU trên macOS, cùng một ứng dụng độc lập để làm việc mà không cần DAW.","featuresPage.cards.offline.title":"Ngoại tuyến, không AI","featuresPage.cards.offline.body":"Không tài khoản, không đo lường từ xa, không mạng và không mô hình. Mọi phần nhạc, cách bấm ngón và chuyển động đều đến từ các quy tắc.","featuresPage.compare.title":"Đặt cạnh nhau","featuresPage.compare.intro":"Freally Handscore 1.0 đặt cạnh những công cụ mà mọi người dùng để viết các phần nhạc hoặc để xem piano được chơi. Các ô của sản phẩm khác lấy từ thông tin công khai và các bài đánh giá về chúng, được kiểm tra vào tháng 10 năm 2026; chỗ nào chúng tôi không thể xác nhận, ô đó sẽ ghi rõ.","featuresPage.compare.feature":"Tính năng","featuresPage.compare.row.generate":"Viết hợp âm, giai điệu và dòng bass mới theo các phong cách được gọi tên","featuresPage.compare.legend.yes":"có","featuresPage.compare.legend.no":"không","featuresPage.compare.row.plugin":"Chạy bên trong DAW của bạn dưới dạng plugin","featuresPage.compare.row.hands":"Hiển thị đôi tay 3D chân thực chơi các nốt","featuresPage.compare.note.library":"thư viện bản nhạc riêng","featuresPage.compare.legend.part":"một phần","featuresPage.compare.note.fingers":"số ngón tay, không có bàn tay","featuresPage.compare.row.sheets":"Hiển thị các nốt dưới dạng bản nhạc","featuresPage.compare.legend.unknown":"chưa xác nhận","featuresPage.compare.row.drag":"Kéo MIDI vào DAW của bạn","featuresPage.compare.row.offline":"Hoạt động ngoại tuyến, không dùng AI","featuresPage.compare.summaryTitle":"Tóm lại","featuresPage.compare.summary":"Trong bốn sản phẩm này, chỉ Handscore 1.0 có đủ mọi hàng: các phần nhạc được viết theo các phong cách được gọi tên, đôi tay chân thực chơi chúng, bản nhạc, thao tác kéo vào DAW của bạn và plugin.","featuresPage.compare.theyWinTitle":"Họ hơn ở đâu","featuresPage.compare.theyWin":"Scaler 3 là một trạm làm việc lý thuyết âm nhạc rộng hơn nhiều. Synthesia được làm để học các bản nhạc trên chính bàn phím của bạn; các bài học của Handscore lắng nghe bạn chơi từ phiên bản 0.6, nhưng chơi theo trực tiếp phải chờ đến phiên bản 1.9. AR Pianist đưa nghệ sĩ piano của nó vào căn phòng của bạn bằng thực tế tăng cường, điều mà Handscore không làm.","featuresPage.compare.fineprint":"Scaler, AR Pianist và Synthesia là nhãn hiệu của các chủ sở hữu tương ứng, vốn không liên kết với Freally Handscore. Nếu một ô nào đó sai, hãy cho chúng tôi biết và chúng tôi sẽ sửa lại.","featuresPage.why.title":"Vì sao nó được làm như vậy","featuresPage.why.rules.title":"Quy tắc, không phải mô hình","featuresPage.why.rules.body":"Mọi phần nhạc, mọi cách bấm ngón và mọi chuyển động đều đến từ các quy tắc, không có mô hình ở bất cứ đâu. Cùng một phong cách và cùng một hạt giống ngẫu nhiên luôn cho ra cùng những phần nhạc, lần nào cũng vậy.","featuresPage.why.drag.title":"Thấy gì thì kéo nấy","featuresPage.why.drag.body":"Các tờ nhạc được vẽ từ chính MIDI mà chúng kéo ra, và đôi tay chơi đúng những nốt đó, nên thứ đáp xuống track của bạn chính là thứ bạn đã xem.","featuresPage.why.real.title":"Làm theo kích thước thật","featuresPage.why.real.body":"Mọi nhạc cụ đều được làm theo kích thước thật của nó: bàn phím có kích thước của một cây đàn piano thật, và mỗi phím xoay trên thanh cân bằng của nó giống như một phím thật.","featuresPage.why.local.title":"Mọi thứ ở lại trên máy của bạn","featuresPage.why.local.body":"Không tài khoản, không đo lường từ xa và không đám mây. Plugin và ứng dụng độc lập không bao giờ lên mạng, và một cổng kiểm tra khi dựng sẽ thất bại nếu mã mạng từng được thêm vào.","featuresPage.coming.title":"Những gì vẫn đang đến","featuresPage.coming.intro":"Nói thẳng, vì một danh sách tính năng giấu đi các thiếu sót thì không đáng đọc. Trang này mô tả phiên bản 1.0, và Handscore được xây từng phiên bản một, nên phần lớn những gì trên trang vẫn chưa được làm. Mỗi phiên bản trên con đường đến 1.0 đều được đánh dấu trạng thái.","featuresPage.limits.title":"Những gì 1.0 không làm","featuresPage.limits.export":"Một bài hát có giai điệu trùng với một bài kinh điển hoặc một giai điệu nổi tiếng chỉ rời khỏi Handscore dưới dạng hợp âm.","featuresPage.limits.families":"Nó chơi các cây piano, guitar và guitar bass. Mọi họ nhạc cụ khác sẽ đến dần qua từng phiên bản sau 1.0, cho đến cả ban nhạc ở 2.0.","featuresPage.limits.learn":"Các bài học của nó lắng nghe bạn chơi, nhưng đôi tay vẫn chưa theo bạn trực tiếp: chơi theo trên bất kỳ nhạc cụ nào sẽ có ở phiên bản 1.9.","featuresPage.coming.downloads":"Không có bản tải xuống nào trước phiên bản 1.0, và cũng không có trên trang này.","docs.intro":"Handscore đang lớn dần thành đôi tay chân thực trên mọi họ nhạc cụ, với các bài học âm nhạc từ piano đến đánh trống bằng ngón tay, sáng tác và phối khí. Cuốn hướng dẫn này lớn lên cùng nó, qua từng phiên bản. Hiện tại nó mô tả những gì phiên bản 0.7.0 làm được: các cây đàn piano và đôi tay, ba góc nhìn, tạo bài hát, bản nhạc, kéo thả và xuất, trình chỉnh sửa, các bài cổ điển, thanh điều khiển phát, các bài học piano, bàn trộn, trình chỉnh sửa đường bao và nhạc cụ của riêng bạn.","docs.start.title":"Bắt đầu","docs.agreement.title":"Thỏa thuận cấp phép","docs.stage.title":"Sân khấu","docs.pianos.title":"Các cây piano","docs.play.title":"Chơi các phím","docs.hands.title":"Đôi tay","docs.views.title":"Các góc nhìn","docs.generate.title":"Tạo bài hát","docs.sheets.title":"Bản nhạc","docs.tray.title":"Khay bản nhạc","docs.drag.title":"Vào DAW của bạn","docs.edit.title":"Chỉnh sửa nốt","docs.lyrics.title":"Lời bài hát","docs.seeds.title":"Hạt giống và lịch sử","docs.classics.title":"Nhạc kinh điển","docs.transport.title":"Thanh điều khiển phát","docs.lessons.title":"Bài học","docs.mixer.title":"Bàn trộn","docs.envelopes.title":"Trình chỉnh sửa đường bao","docs.hosted.title":"Nhạc cụ của riêng bạn","docs.shortcuts.title":"Phím tắt","docs.project.title":"Dự án của bạn","docs.theme.title":"Sáng và tối","docs.language.title":"Ngôn ngữ","docs.privacy.title":"Quyền riêng tư của bạn","docs.start.p1":"Handscore chạy bên trong DAW của bạn như một nhạc cụ CLAP, VST3 hoặc AU, hoặc chạy riêng như một ứng dụng độc lập. Hãy đặt nó lên một track nhạc cụ.","docs.start.p2":"Chưa có bản tải xuống nào trước phiên bản 1.0.0, và mã nguồn là riêng tư.","docs.agreement.p1":"Lần đầu mở, Handscore hiện ra thỏa thuận cấp phép của nó. Cho đến khi bạn chọn Đồng ý, Handscore không làm gì và không phát ra âm thanh nào.","docs.agreement.p2":"Câu trả lời của bạn được lưu trên máy tính của bạn và dùng chung cho mọi bản Handscore đang mở, trong mọi DAW và trong ứng dụng độc lập. Nếu bạn từ chối, thỏa thuận vẫn ở trên màn hình, sẵn sàng cho bất cứ khi nào bạn đồng ý.","docs.stage.p1":"Bên dưới thanh trên cùng là sân khấu: cây đàn piano bạn đã chọn, với 88 phím, từ A0 đến C8, theo đúng kích thước của một cây đàn piano thật, trải kín chiều rộng cửa sổ. Tên của mỗi phím nằm ở mặt trước của nó — phím trắng in mực tối, phím đen in màu trắng — và ẩn đi khi phím đang được nhấn, nên bạn luôn thấy những nốt nào đang được chơi.","docs.stage.p2":"Nếu máy tính của bạn không thể vẽ 3D, sân khấu sẽ nói rõ điều đó và giải thích cách bật nó lên, thay vì không hiển thị gì.","docs.stage.p3":"Handscore đo xem máy tính của bạn vẽ sân khấu nhanh đến đâu và chọn mức chất lượng mà máy có thể duy trì mượt mà.","docs.pianos.p1":"Bốn cây piano lần lượt lên sân khấu, mỗi lần một cây: Grand Piano, Acoustic Piano, Upright Piano và Honky-Tonk Piano, mỗi cây có hình dáng, lớp hoàn thiện và âm thanh riêng.","docs.pianos.p2":"Nút Chọn chế độ ở góc trên bên trái (hoặc P) mở các lựa chọn của bạn theo danh mục. Trong Nhạc cụ, Nghe thử chơi một câu nhạc ngắn trên một cây piano mà không đổi đàn, còn Chọn đưa nó lên sân khấu, chuyển tiếp mượt mà từ cây trước đó. Lựa chọn của bạn được lưu cùng dự án.","docs.play.p1":"Nhấp vào một phím để nghe nó, hoặc lướt qua các phím để chơi lần lượt từng phím. Mỗi phím đi xuống bằng cách xoay trên thanh cân bằng của nó, được chơi càng mạnh thì xuống càng nhanh, và tên của phím mờ đi khi phím đang xuống rồi hiện lại khi phím nâng lên.","docs.play.p2":"MIDI từ DAW của bạn chơi cây piano và làm các phím của nó chuyển động. Pedal sustain giữ những nốt bạn buông ra cho đến khi bạn nhấc chân khỏi pedal.","docs.hands.p1":"Hai bàn tay chân thực chơi mọi nốt trên sân khấu theo cách một nghệ sĩ piano sẽ chơi: mỗi ngón được chọn cho đoạn nhạc, ngón cái luồn xuống dưới khi chạy gam, vươn tới những hợp âm rộng, và một bàn tay nhấc lên vượt qua tay kia khi bản nhạc đòi hỏi bắt chéo tay. Khi không có gì đang chơi, đôi tay đặt trên phím, sẵn sàng.","docs.hands.p2":"Handscore tính trước tay nào chơi mỗi nốt, và bằng ngón nào, trước khi nhạc vang lên, nên đôi tay đến đúng lúc phím đi xuống.","docs.views.p1":"Xem sân khấu từ phía trước, từ trên xuống hoặc từ bên cạnh. Xoay núm góc nhìn ở góc trên bên phải sân khấu, hoặc nhấn V để sang góc nhìn kế tiếp và Shift+V để về góc nhìn trước. Máy quay lướt từ góc nhìn này sang góc nhìn kế tiếp trong khi nhạc vẫn chơi, và mọi phím, mọi bàn tay, mọi nốt sáng vẫn đúng nhịp. Dự án của bạn ghi nhớ góc nhìn.","docs.views.p2":"Trước là góc nhìn của người chơi, bàn phím lấp đầy cửa sổ. Trên nhìn thẳng xuống phím đàn và đôi tay: đàn grand đóng nắp lại, và các bản nhạc nằm phẳng cạnh nhau trên nắp để bạn đọc; với đàn upright, chúng nằm trên nắp trên. Bên nhìn dọc bàn phím từ đầu âm cao, ngang tầm phím, để thấy hình dáng đôi tay — mỗi ngón cong thế nào và mỗi phím nhấn xuống sâu bao nhiêu — với các bản nhạc trên giá xoay về phía bạn. Ở góc nhìn Bên, công tắc Từ bên trái dưới núm góc nhìn sẽ nhìn từ đầu âm trầm thay vào đó. Nhấp vào một bản nhạc, hoặc nhấn từ 1 đến 5, để xem gần ở bất kỳ góc nhìn nào.","docs.generate.p1":"Bảng bên trái (thẻ của nó ở mép cửa sổ hiện và ẩn bảng) tìm trong 73 thể loại, 1.507 nghệ sĩ và 833 nhà sản xuất. Chọn một và nhấn Tạo, hoặc G: bốn bè — hợp âm, giai điệu, bè phụ và bè trầm — được viết theo phong cách đó, dài 4 hoặc 8 ô nhịp, và đôi tay chơi chúng trên đàn piano.","docs.generate.p2":"Các nút bên cạnh Tạo đặt giọng, thang âm (41 lựa chọn), cảm xúc, nhịp độ (20 đến 999 BPM; kéo con số lên hoặc xuống), độ phức tạp và 4 hoặc 8 ô nhịp, và mỗi nút cho biết bài hát được làm theo gì. Theo DAW viết theo nhịp độ dự án của bạn. Chơi được sắp các bè cho hai tay; Nguyên bản giữ chúng đúng như đã viết.","docs.sheets.p1":"Mỗi bè được in thành một trang bản nhạc trên giá nhạc của đàn, có tiêu đề và số trang, và tổng phổ của tất cả các bè đặt bên cạnh. Mỗi đầu nốt sáng lên khi vang dưới con trỏ phát đang chạy, và một bè dài tự lật trang khi chơi. Nhấp vào một bản nhạc, hoặc nhấn 1 đến 5, để đưa nó lại gần; Esc để quay lại.","docs.tray.p1":"Dưới sân khấu, khay chứa từng bè với Độc tấu, Tắt tiếng, Khóa và một bản thu mới. Một bè đã khóa sẽ được giữ lại khi bạn tạo lần nữa. Bản thu, Mơ 1–3 và Mơ lại đưa ra ba phiên bản mới của một bè bên cạnh bản bạn đang có: chọn một và giữ lại.","docs.drag.p1":"Kéo một bè từ bản nhạc của nó, hoặc cả bài với Kéo tất cả, thẳng vào DAW của bạn dưới dạng MIDI. Xuất lưu MIDI của một bè hoặc cả bài vào tệp do bạn đặt tên, với lực nhấn của từng nốt, mức âm lượng và pan của từng bè, nhịp độ và số chỉ nhịp.","docs.drag.p2":"Xuất ra PDF ghi bản nhạc kèm trang bìa: tiêu đề, nhịp độ, giọng và thang âm, độ dài, số ô nhịp, số nốt tổng cộng, theo từng bè và từng trang, và các nhạc cụ. Thêm phần ghi công — tác giả, ca sĩ, nhà sản xuất, các sample bạn đã dùng và nguồn của chúng, hãng thu âm — với tên được gợi ý khi bạn gõ.","docs.edit.p1":"Sân khấu, Giai điệu, Hợp âm, Bè phụ và Bè trầm nằm ở phía trên. Thẻ của một bè mở piano roll riêng của nó, với một chấm tắt tiếng, Độc tấu và dấu × để xóa bè. Chọn, di chuyển, kéo dài, xóa, sao chép, dán và nhân bản nốt; nhấp chuột phải và kéo để lấy nốt đi rồi trả lại. Mỗi bè có gain và pan riêng.","docs.edit.p2":"Thu từ bàn phím MIDI vào roll sau khi đếm một hoặc hai ô nhịp. Thu gọn roll theo thang âm của bài, hoặc theo các hàng có nốt: các hàng của thang âm được tô màu và nốt nằm ngoài được đánh dấu. Khi bạn vẽ, nốt hoặc hợp âm tiếp theo được gợi ý mờ mờ; Tab giữ lại, một cú nhấp giữ một nốt, và vẽ ở chỗ khác sẽ xóa gợi ý.","docs.edit.p3":"Bật Hợp âm bên cạnh thanh điều khiển phát và một phím sẽ chơi một hợp âm 3, 4 hoặc 5 nốt theo giọng của bài, bằng chuột, bàn phím máy tính hoặc bàn phím MIDI.","docs.lyrics.p1":"Gõ lời dưới giai điệu hoặc bè phụ, các âm tiết được đánh dấu: chúng được in lên bản nhạc và sáng lên khi được hát. Bộ đếm bên cạnh mỗi dòng cho biết dòng đó có vừa ô nhịp không. Khi bạn gõ, phần còn lại của từ được gợi ý (Tab để nhận) và lỗi chính tả được sửa, trừ khi bạn chạm dấu kiểm hoặc nhấn Shift+Tab để giữ từ của mình.","docs.seeds.p1":"Mỗi lần tạo hiển thị hạt giống của nó, và mỗi bè hiển thị hạt giống bản thu, kèm Sao chép. Dán hạt giống của một bài để tạo lại bài đó, hoặc hạt giống bản thu của một bè để lấy lại bản thu ấy. Lùi và Tiến đi qua mọi lần tạo bạn đã làm, mỗi lần được đưa về chính xác và được giữ qua các lần khởi động lại; một lần tạo mới không bao giờ lặp lại lần cũ.","docs.classics.p1":"Mục Bài kinh điển trong Chọn chế độ có sáu mươi hai bài hát thuộc phạm vi công cộng để học: bài hát thiếu nhi, nhạc Giáng sinh và thánh ca Giáng sinh, dân ca, nhạc spiritual và quốc ca, các chủ đề cổ điển và những bản piano được yêu thích. Mỗi bài được soạn cho hai tay, giai điệu ở tay phải và hợp âm ở tay trái. Tìm theo tên bài hoặc nhà soạn nhạc, rồi chọn Phát.","docs.classics.p2":"Bài cổ điển là để học, không phải để lấy: chỉ hợp âm của nó mới được rời khỏi Handscore. Một bài được tạo có giai điệu, bè phụ hoặc bè trầm giống một giai điệu nổi tiếng sẽ giữ bè đó lại trong ứng dụng, và nói rõ lý do.","docs.transport.p1":"Bên dưới sân khấu: tua lại, phát hoặc tạm dừng, dừng và tua nhanh, cùng một dòng thời gian hiển thị thời gian của bài và một vạch ở mỗi ô nhịp. Di chuột lên dòng thời gian để xem đôi tay tại thời điểm đó trong một bản xem trước nhỏ; nhấp hoặc kéo để đến đó. Nhấn giữ tua lại hoặc tua nhanh để di chuyển nhanh. Dù cách nào, bạn cũng nghe thấy mọi nốt bạn đi qua. Phím cách để phát và tạm dừng, còn các phím mũi tên trên dòng thời gian bước từng ô nhịp.","docs.transport.p2":"Chữ M bên cạnh các phím là máy đếm nhịp. Bật nó lên và một tiếng tích đánh dấu mỗi phách, phách đầu của mỗi ô nhịp cao hơn, trong khi hai chấm của nó hiển thị phách.","docs.transport.p3":"Khi bài hát có lời, bản xem trước trên dòng thời gian hiển thị những lời đang được hát vào lúc đó.","docs.lessons.p1":"Chọn chế độ → Bài học mở khóa piano ngay trong studio: bản đồ khóa học và các bước của ngày ở bên trái, sân khấu ở giữa và phần chữ của bài ở bên dưới. Khóa học đi từng ngày — Nhập môn, ngày 1 đến 90, rồi Cơ bản, ngày 91 đến 400 — mỗi ngày là một buổi học có hướng dẫn, kèm một ngày ôn tập mỗi tuần. Lần đầu, khóa học mở ở ngày 1; sau đó, Tiếp tục đưa bạn về thẳng ngày, bước và từ nơi bạn đã dừng. Ngày nào cũng mở được từ bản đồ, và Thoát bài học quay về bài hát bạn đã để lại.","docs.lessons.p2":"Mỗi bước đọc, làm mẫu hoặc lắng nghe. Xem: đôi tay chơi bài tập ở góc nhìn mà bước chỉ định, chậm nếu bước yêu cầu, có số ngón tay. Thử: các phím cần chơi sáng lên và nhạc chờ bạn. Theo nhịp: đúng tempo sau phần đếm vào, mỗi nốt được so với phách. Chơi trọn bài: chơi từ đầu đến cuối, có phần tóm tắt ở cuối. Mỗi lần chơi nêu ô nhịp và phách và chỉ cách sửa. Một bước đạt sau vài lần chơi đúng liên tiếp, còn một ngày đạt khi bài tập chính được chơi trọn vẹn — đúng nhịp, nếu ngày đó luyện nó theo nhịp. Để luyện, lặp lại vài ô nhịp, chơi một tay trong khi sân khấu chơi tay kia, hoặc đổi tempo; trên thang tempo, nhịp tăng sau ba lần chơi sạch và lùi một bậc sau ba lần sai. Thử cũng dùng được chuột trên các phím của sân khấu; Theo nhịp và Chơi trọn bài cần bàn phím MIDI.","docs.lessons.p3":"Đọc to tắt cho đến khi bạn bật. Khi đó giọng đọc của chính máy tính đọc bài, mỗi từ sáng lên khi được đọc. Phím Cách phát và tạm dừng, ⏹ dừng, giữ ⏪ hoặc ⏩ để lùi hoặc tiến; chỉnh tốc độ từ một nửa đến gấp đôi và chọn giọng trong số giọng đã cài. Các đồng hồ cho thấy thời gian trong ngày này và trong tất cả, cùng số ngày bạn đã luyện tập. Tiến độ của bạn ở lại trên máy tính này, giống nhau trong ứng dụng độc lập và trong mọi DAW, và không bao giờ đi vào một dự án.","docs.mixer.p1":"Nhấn M, hoặc thẻ Bàn trộn, để xem kênh của mọi bè nằm cạnh nhau cùng kênh tổng. Mỗi kênh có một fader, một núm vị trí, EQ ba dải, Phòng, Vọng và Nhiệt, một bộ nén (tắt cho đến khi bạn bật) và núm Hạt, cùng một đồng hồ mức LED và đèn quá mức; kênh tổng có fader, núm Hạt và đồng hồ mức riêng. Kéo fader trong khi giữ Shift để chỉnh tinh, hoặc nhấp đúp vào nó để về 0 dB. Tắt tiếng và độc tấu chuyển mượt thay vì cắt ngang; Ctrl+click vào một nút độc tấu để thêm một bè vào đó. Mỗi thay đổi đều nghe được khi bạn đang chỉnh và thành một bước hoàn tác khi bạn thả tay, và dự án giữ lại bản trộn.","docs.mixer.p2":"Bên dưới các bản nhạc, tay nắm âm thanh của mỗi bè kéo bè đó vào DAW của bạn dưới dạng WAV, xuất qua kênh của nó theo nhịp độ của bài; cả bản trộn được kéo đúng như bạn nghe và nêu tên các bè bị bỏ ra. Kéo MIDI mang theo fader và vị trí của bè dưới dạng controller và cho biết những gì MIDI không mang được.","docs.envelopes.p1":"Trên thẻ của một bè, nút Đường bao mở các đường bao của bè đó: âm lượng, bộ lọc, cao độ, vị trí và Hạt, mỗi đường đều tắt cho đến khi bạn bật. Kéo một điểm, hoặc kéo hình thoi của một đoạn để uốn cong nó; nhấp đúp để thêm điểm, hoặc nhấp đúp vào một điểm để bỏ nó; chọn một điểm để gõ các giá trị của nó, hoặc di chuyển nó bằng phím mũi tên. Mỗi đường bao có độ sâu, tỉ lệ thời gian, theo lực nhấn và theo phím, một vòng lặp được giữ, thời gian khóa theo nhịp độ, kích hoạt lại, liền tiếng hoặc đặt lại mỗi ô nhịp, và chuyển A/B. Bắt đầu từ một hình dạng, sao chép đường bao sang bè khác, hoàn tác và làm lại, hoặc đặt lại tất cả; trong khi bài hát phát, một chấm cho mỗi nốt chạy trên đường cong.","docs.hosted.p1":"Mỗi bè có thể chơi bằng một nhạc cụ VST3 hoặc CLAP của riêng bạn thay cho nhạc cụ của Handscore. Trên thẻ của bè hoặc kênh của nó trong bàn trộn, nút nhạc cụ mở bộ chọn: nhạc cụ của Handscore đứng đầu, rồi đến mọi nhạc cụ mà lần quét tìm thấy trong các thư mục plugin tiêu chuẩn và trong các thư mục bạn thêm vào. Chọn một và bè đó phát qua nhạc cụ ấy, cửa sổ của nó chỉ cách một cú nhấp; dự án giữ plugin cùng âm thanh của nó. Mỗi plugin chạy trong tiến trình riêng, nên plugin nào bị sập chỉ tự dừng chính nó, và độ trễ của nó được bù trừ. Đôi tay vẫn ở trên nhạc cụ của Handscore, và bè đó được kéo dưới dạng MIDI. Một plugin mà dự án của bạn ghi tên nhưng máy tính này không có sẽ được thay bằng nhạc cụ của Handscore, và bè đó sẽ báo cho bạn. Trong phiên bản này, cửa sổ plugin mở được trên Windows.","docs.shortcuts.p1":"Nhấn ? hoặc phím Phím tắt trên thanh trên cùng để xem mọi phím tắt.","docs.project.p1":"Lưu dự án DAW sẽ giữ bài hát, các chỉnh sửa, bản mix, lời, đàn piano, góc nhìn và phần ghi công, và khi mở lại mọi thứ trở về như cũ.","docs.theme.p1":"Công tắc Giao diện tối ở góc trên bên phải chuyển cửa sổ sang sáng hoặc tối. Handscore ghi nhớ lựa chọn của bạn, và các ứng dụng Freally khác trên máy tính của bạn cũng vậy.","docs.language.p1":"Handscore nói được mười tám ngôn ngữ và khởi động bằng ngôn ngữ hệ thống của bạn.","docs.privacy.p1":"Plugin và ứng dụng độc lập không bao giờ dùng mạng. Nếu Handscore có lúc dừng đột ngột, một báo cáo ngắn sẽ được lưu trên máy tính của bạn và được đưa ra vào lần mở tiếp theo; không có gì được gửi đi trừ khi bạn chọn báo cáo sự cố.","kit.skip":"Chuyển đến nội dung","kit.nav.site":"Trang web","kit.nav.home":"Trang chủ","kit.nav.features":"Tính năng","kit.nav.documentation":"Tài liệu","kit.nav.changelog":"Nhật ký thay đổi","kit.nav.language":"Ngôn ngữ","kit.nav.allApps":"Tất cả ứng dụng Freally","kit.badge.progress":"v0.7.0 đã xong · tiếp theo là v0.8.0","kit.cta.features":"Xem mọi tính năng","kit.cta.docs":"Đọc tài liệu","kit.price":"Freally Handscore hiện miễn phí, nhưng có thể không miễn phí mãi mãi: các phiên bản sau này có thể được bán.","kit.noDownloads":"Hiện chưa có bản tải xuống, và mã nguồn là riêng tư.","kit.label.overview":"Tổng quan","kit.label.inside":"Bên trong","kit.label.roadmap":"Lộ trình","kit.ladder.done":"Xong","kit.ladder.planned":"Đã lên kế hoạch","kit.ladder.goal":"Mục tiêu","kit.ladder.later":"Về sau","kit.label.honesty":"Trung thực","kit.family.label":"Gia đình Freally","kit.family.title":"<span class=\"hl-muted\">Một gia đình.</span> <span class=\"hl-bright\">Mười ứng dụng.</span>","kit.cta.label":"Những gì đã thay đổi","kit.cta.title":"<span class=\"hl-muted\">Mỗi phiên bản,</span> <span class=\"hl-bright\">đều được ghi lại.</span>","kit.cta.lede":"Nhật ký thay đổi liệt kê mọi thứ đã thay đổi trong Freally Handscore, theo từng phiên bản, bằng cả mười tám ngôn ngữ.","kit.cta.changelog":"Đọc nhật ký thay đổi","kit.footer.thisApp":"Ứng dụng này","kit.footer.family":"Gia đình Freally","kit.status.devVersion":"Đang phát triển · v0.7.0","kit.head.features":"<span class=\"hl-muted\">Mọi thứ nó làm được,</span> <span class=\"hl-bright\">đặt cạnh nhau.</span>","kit.label.numbers":"Qua các con số","kit.numbers.lead":"Mỗi con số đều được đếm từ chính ứng dụng. Không có gì là ước tính, và không có gì được làm tròn lên.","kit.label.free":"Miễn phí hôm nay","kit.label.compare":"So sánh","kit.label.principles":"Nguyên tắc","kit.label.limits":"Giới hạn","kit.states.title":"Ý nghĩa của các trạng thái","kit.states.done":"đã dựng và gắn thẻ, nhưng không phải bản tải xuống trên trang này","kit.states.planned":"vẫn chưa được xây dựng","kit.states.goal":"phiên bản mà con đường này hướng tới","kit.states.later":"sau đó, và chưa được lên lịch","kit.states.ladder":"Xem mọi nấc trên con đường","kit.head.documentation":"<span class=\"hl-muted\">Cách hoạt động,</span> <span class=\"hl-bright\">từng bước một.</span>","kit.search.placeholder":"Tìm kiếm trong tài liệu","kit.docs.contents":"Mục lục","kit.head.changelog":"<span class=\"hl-muted\">Mọi thay đổi,</span> <span class=\"hl-bright\">theo từng phiên bản.</span>","kit.changelog.lede":"Mới nhất trước: mọi thứ đã thay đổi trong Freally Handscore, bằng mọi ngôn ngữ của trang này.","kit.changelog.versions":"Phiên bản","kit.search.none":"Không có gì trên trang này khớp với điều đó.","kit.zoom.close":"Đóng","changelog.9960bf9700bd":"<span class=\"release__meta\"><span class=\"release__ver\">v0.7.0</span><time class=\"release__date\" datetime=\"2026-10-16\">2026-10-16</time></span>","changelog.89f5c24a8af1":"Bàn trộn. Giờ đây mỗi bè phát qua kênh riêng của nó — fader, vị trí, EQ, phòng, vọng, nhiệt, một bộ nén và một núm Hạt — vào kênh tổng, có đồng hồ mức, tắt tiếng và độc tấu, tất cả được lưu cùng dự án của bạn. Kéo bất kỳ bè nào, hoặc cả bản trộn, vào DAW của bạn dưới dạng âm thanh, đúng như bạn đang nghe. Tạo hình âm thanh của từng bè bằng trình chỉnh sửa đường bao, và cho bất kỳ bè nào chơi bằng một nhạc cụ VST3 hoặc CLAP của riêng bạn.","changelog.6b02e0d363a4":"Đã thêm","changelog.8b1d7b62602b":"<strong>Bàn trộn.</strong> Nhấn M: kênh của mọi bè nằm cạnh nhau cùng kênh tổng — một fader có vạch in theo sát con trỏ của bạn, một đồng hồ mức LED với đèn quá mức, lưới núm (Trầm, Trung, Cao, Phòng, Vọng, Nhiệt), một bộ nén với đèn báo mức nén, vị trí, độc tấu và tắt tiếng. Mỗi thao tác đều nghe được ngay khi đang di chuyển và thành một bước hoàn tác khi bạn thả tay.","changelog.2869671be357":"<strong>Tắt tiếng và độc tấu mượt mà.</strong> Một bè nhỏ dần rồi trở lại trong 30 ms thay vì bị cắt ngang, và độc tấu chỉ cho nghe các bè đang độc tấu — Ctrl+click để thêm một bè.","changelog.fcb6690799bd":"<strong>Núm Hạt.</strong> Trên mọi kênh và trên kênh tổng: từ không có gì ở 0 % đến một đám mây hạt, tiếng vọng và một lớp âm phủ ở 100 %, một âm thanh biến bất kỳ bè nào thành ambient. Hạt giống lấy từ dự án, nên mỗi lần xuất đều cho kết quả giống hệt.","changelog.57a83d56df21":"<strong>Kéo âm thanh.</strong> Tay nắm âm thanh của mỗi bè kéo bè đó thành tệp WAV 24-bit, xuất qua kênh của nó theo nhịp độ của bài; cả bản trộn được kéo đúng như bạn nghe và nêu tên các bè bị bỏ ra.","changelog.b2176c506737":"<strong>Kéo MIDI mang theo bản trộn.</strong> Fader và vị trí của một bè đi vào tệp dưới dạng CC 7 và CC 10, và tay nắm liệt kê những gì MIDI không mang được.","changelog.5b174d5cb7c6":"<strong>Trình chỉnh sửa đường bao.</strong> Các đường bao Âm lượng, Bộ lọc, Cao độ, Vị trí và Hạt của mỗi bộ tạo, mỗi đường đều tắt cho đến khi bạn bật: điểm để kéo, đoạn để uốn cong, một vòng lặp được giữ, thời gian khóa theo nhịp độ, theo lực nhấn và theo phím, kích hoạt lại hoặc liền tiếng, chuyển A/B, hình dạng khởi đầu, sao chép sang bè khác, hoàn tác và làm lại, và một chấm trực tiếp cho mỗi nốt chạy trên đường cong.","changelog.747aa74c96df":"<strong>Nhạc cụ của riêng bạn.</strong> Mỗi bè có thể chơi bằng một nhạc cụ VST3 hoặc CLAP của riêng bạn thay cho nhạc cụ của Handscore: chọn nó trên thẻ hoặc kênh của bè, trong số các nhạc cụ mà lần quét tìm thấy, mở cửa sổ của nó từ đó, và dự án của bạn giữ plugin cùng âm thanh của nó. Mỗi plugin chạy trong tiến trình riêng, nên plugin nào bị sập chỉ tự dừng chính nó, và độ trễ của nó được bù trừ. Đôi tay vẫn ở trên nhạc cụ của Handscore, và bè đó được kéo dưới dạng MIDI.","changelog.ddebf2581fd7":"<span class=\"release__meta\"><span class=\"release__ver\">v0.6.0</span><time class=\"release__date\" datetime=\"2026-10-16\">2026-10-16</time></span>","changelog.1d54e0107a4f":"Bài học. Giờ đây Handscore dạy piano, từng ngày một, từ những nốt đầu tiên của bạn đến khoảng trình độ cấp 2: 400 ngày trong hai phần, Nhập môn và Cơ bản, mỗi ngày là một buổi học có hướng dẫn riêng. Đôi tay làm mẫu từng bài tập từ bất kỳ góc nhìn nào, rồi khóa học lắng nghe bạn chơi trên bàn phím MIDI và chỉ đi tiếp khi đã đúng. Bật Đọc to và giọng đọc của chính máy tính sẽ đọc bài cho bạn, mỗi từ sáng lên khi được đọc.","changelog.7cf885e0b28b":"<strong>Bài học ngay trong studio.</strong> Chọn chế độ → Bài học mở khóa piano: bản đồ khóa học và các bước của ngày ở bên trái, sân khấu ở giữa, phần chữ của bài ở bên dưới. Thoát bài học đưa bạn về bài hát bạn đã để lại.","changelog.1c23de3f48f7":"<strong>400 ngày piano.</strong> Nhập môn (ngày 1–90) và Cơ bản (ngày 91–400): tư thế ngồi và dáng tay, các thế năm ngón, đọc khuông nhạc đôi, nhịp điệu, hợp âm, pedal, gam và rải hợp âm, hai tay cùng chơi và những bản nhạc để chơi, với một ngày ôn tập mỗi tuần và bài cũ quay lại khi đến lúc.","changelog.1a00ed521da6":"<strong>Lắng nghe và kiểm tra, theo ba cách.</strong> <em>Thử</em>: các phím cần chơi sáng lên và nhạc chờ bạn. <em>Theo nhịp</em>: đúng tempo sau phần đếm vào, mỗi nốt được so với phách. <em>Chơi trọn bài</em>: chơi từ đầu đến cuối, có phần tóm tắt ở cuối.","changelog.93f77c21d390":"<strong>Nhận xét như của một giáo viên.</strong> Mỗi lần chơi nêu ô nhịp và phách, chỉ cách sửa — một nốt bị bỏ sót, sớm hay muộn, liền hay ngắt, pedal — và nói điều gì đã tốt.","changelog.03b65d4d96a6":"<strong>Công cụ luyện tập.</strong> Lặp lại vài ô nhịp, chơi một tay trong khi sân khấu chơi tay kia, leo thang tempo (lên một bậc sau ba lần chơi sạch, lùi một bậc sau ba lần sai) và xem phần làm mẫu chậm ở bất kỳ góc nhìn nào, có số ngón tay. Tên phím mờ dần khi bạn đã thuộc.","changelog.deb6f2d0e7f9":"<strong>Đọc to.</strong> Tắt cho đến khi bạn bật, và được ghi nhớ. Giọng đọc của máy tính đọc bài, từ đang đọc sáng lên như màn hình karaoke và chữ cuộn theo để luôn hiện trong khung. Phát và tạm dừng bằng phím Cách, dừng, giữ ⏪ hoặc ⏩ để lùi hay tiến, chỉnh tốc độ từ một nửa đến gấp đôi và chọn giọng; một đồng hồ cho biết thời gian đọc đã qua và còn lại.","changelog.b9d693ff0bb1":"<strong>Tiến độ của bạn, được lưu.</strong> Những ngày bạn đã vượt qua, thời gian trong từng bài và trong tất cả, và những ngày bạn đã luyện tập, tính theo ngày, giờ, phút và giây — trên máy tính này, trong ứng dụng độc lập và trong mọi DAW. Tiếp tục mở đúng chỗ bạn đã dừng: ngày, bước và từ.","changelog.2f7168838eb6":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.0</span><time class=\"release__date\" datetime=\"2026-10-15\">2026-10-15</time></span>","changelog.cb681d22c8c6":"Góc nhìn từ trên và từ bên. Ngắm đôi tay từ phía trước, từ ngay phía trên hoặc từ bên cạnh, và lướt từ góc nhìn này sang góc nhìn khác trong khi nhạc vẫn chơi — phím đàn, đôi tay và các nốt sáng không lỡ một phách nào. Nhìn từ trên, đàn grand đóng nắp và các bản nhạc nằm phẳng trên đó, sẵn sàng để đọc; nhìn từ bên, hình dáng đôi tay hiện rõ: mỗi ngón cong thế nào và mỗi phím nhấn xuống sâu bao nhiêu.","changelog.92ffe6279372":"<strong>Ba góc nhìn: Trước, Trên và Bên.</strong> Xoay núm góc nhìn ở góc trên bên phải sân khấu, hoặc nhấn V để sang góc nhìn kế tiếp và Shift+V để về góc nhìn trước. Dự án của bạn ghi nhớ góc nhìn.","changelog.51b3e3c98cbc":"<strong>Chuyển cảnh liền mạch.</strong> Máy quay lướt từ góc nhìn này sang góc nhìn kế tiếp mà không bao giờ xuyên qua cây đàn, và nhạc vẫn chơi suốt lúc chuyển: mọi phím, mọi bàn tay và mọi nốt sáng đều ở đúng chỗ như khi máy quay đứng yên.","changelog.24e5e2980ffb":"<strong>Trên: phím đàn và đôi tay nhìn từ trên xuống.</strong> Đàn grand gập que chống, hạ giá nhạc nằm phẳng và đóng nắp; các bản nhạc rời giá, chờ phía trên phím đàn rồi nằm cạnh nhau trên nắp đã đóng, đọc xuôi chiều từ chỗ bạn ngồi. Với đàn upright, các bản nhạc nằm trên nắp trên.","changelog.ea29eaefbaec":"<strong>Bên: đôi tay nhìn nghiêng.</strong> Máy quay nhìn dọc bàn phím từ đầu âm cao, ngang tầm phím — hoặc từ đầu âm trầm, với <em>Từ bên trái</em> dưới núm góc nhìn — và các bản nhạc xoay trên giá về phía nó để vẫn đọc được.","changelog.49ab9c89770a":"<strong>Đôi tay từ mọi phía.</strong> Bóng của chúng đổ trên những phím chúng chơi, và nhìn từ trên không đầu ngón nào lún vào phím hay vào thân đàn.","changelog.31bd22333d53":"<strong>Xem gần bản nhạc ở mọi góc nhìn.</strong> Nhấp vào bản nhạc, hoặc nhấn từ 1 đến 5; Esc quay về góc nhìn.","changelog.7acb71645827":"<strong>Mượt mà ở mọi góc nhìn.</strong> Sau mỗi lần đổi góc nhìn hoặc cây đàn, Handscore kiểm tra lại sân khấu vẽ mượt đến đâu, và nếu chậm đi thì giảm chất lượng và báo cho bạn.","changelog.d524626e7e53":"<span class=\"release__meta\"><span class=\"release__ver\">v0.4.0</span><time class=\"release__date\" datetime=\"2026-10-15\">2026-10-15</time></span>","changelog.1afdc18898f2":"Tạo, đọc và kéo thả. Tìm trong 73 thể loại, 1.507 nghệ sĩ hoặc 833 nhà sản xuất, nhấn Tạo, và bốn bè — hợp âm, giai điệu, bè phụ và bè trầm — được viết theo phong cách đó và được đôi tay chơi trên đàn piano. Mỗi bè được in thành bản nhạc thật trên giá nhạc của đàn, bên cạnh tổng phổ, và mỗi nốt sáng lên khi vang. Kéo một bè, hoặc cả bài, thẳng vào DAW của bạn, chỉnh bất kỳ nốt nào trong piano roll riêng của nó, và xuất MIDI hoặc PDF bản nhạc kèm phần ghi công của bạn.","changelog.e5fa15165f43":"<strong>Tạo theo mọi phong cách.</strong> Tìm một thể loại, nghệ sĩ hoặc nhà sản xuất trong bảng bên trái (thẻ của nó ở mép ứng dụng hiện và ẩn bảng) rồi nhấn Tạo, hoặc G. Các nút bên cạnh đặt giọng, thang âm (41 lựa chọn), cảm xúc, nhịp độ (20 đến 999 BPM; kéo con số lên hoặc xuống), độ phức tạp và 4 hoặc 8 ô nhịp, và mỗi nút cho biết bài hát được làm theo gì. <em>Theo DAW</em> viết theo nhịp độ dự án của bạn.","changelog.9b105b8264c8":"<strong>Bốn bè, do đôi tay chơi.</strong> Hợp âm, giai điệu, bè phụ và bè trầm, được sắp cho hai tay (<em>Chơi được</em>) hoặc đúng như đã viết (<em>Nguyên bản</em>). Mỗi lần tạo lấp đầy 4 hoặc 8 ô nhịp của nó, và chuyển từ 4 sang 8 sẽ lặp lại bốn ô đầu.","changelog.99862da9695f":"<strong>Bản nhạc thật.</strong> Mỗi bè được in thành một trang trên giá nhạc, có tiêu đề và số trang, cùng tổng phổ của tất cả các bè bên cạnh. Mỗi đầu nốt sáng lên khi vang dưới con trỏ phát đang chạy, và một bè dài tự lật trang khi chơi. Nhấp vào một bản nhạc, hoặc nhấn 1 đến 5, để đưa nó lại gần; Esc để quay lại.","changelog.4ed6b96e134b":"<strong>Khay bản nhạc.</strong> Dưới sân khấu, mỗi bè có Độc tấu, Tắt tiếng, Khóa và một bản thu mới. Một bè đã khóa sẽ được giữ lại khi bạn tạo lần nữa.","changelog.2b9c198c01ea":"<strong>Kéo vào DAW của bạn.</strong> Kéo một bè, hoặc cả bài với <em>Kéo tất cả</em>, từ bản nhạc của nó vào DAW của bạn dưới dạng MIDI.","changelog.471d0e4ba86d":"<strong>Xuất.</strong> Lưu MIDI của một bè hoặc cả bài, với lực nhấn của từng nốt, mức âm lượng và pan của từng bè, nhịp độ và số chỉ nhịp.","changelog.142257343a9f":"<strong>Xuất ra PDF.</strong> Một PDF bản nhạc có trang bìa: tiêu đề, nhịp độ, giọng và thang âm, độ dài, số ô nhịp, số nốt tổng cộng, theo từng bè và từng trang, và các nhạc cụ. Thêm phần ghi công — tác giả, ca sĩ, nhà sản xuất, các sample bạn đã dùng và nguồn của chúng, hãng thu âm — với tên được gợi ý khi bạn gõ.","changelog.1531fe3dfe30":"<strong>Một thẻ cho mỗi bè.</strong> Sân khấu, Giai điệu, Hợp âm, Bè phụ và Bè trầm ở phía trên; thẻ của mỗi bè có piano roll riêng và một chấm tắt tiếng, Độc tấu và dấu × để xóa bè.","changelog.dc61e3f5b735":"<strong>Chỉnh sửa nốt.</strong> Chọn, di chuyển, kéo dài, xóa, sao chép, dán và nhân bản nốt trong roll của bất kỳ bè nào; nhấp chuột phải và kéo để lấy nốt đi rồi trả lại. Thu từ bàn phím MIDI vào roll sau khi đếm một hoặc hai ô nhịp. Mỗi bè có gain và pan riêng.","changelog.0cb3c4c9fd20":"<strong>Thang âm trên roll.</strong> Thu gọn roll theo thang âm của bài hoặc theo các hàng có nốt; các hàng của thang âm được tô màu và nốt nằm ngoài được đánh dấu.","changelog.0ef6f26c2429":"<strong>Hợp âm một phím.</strong> Bật lên và một phím sẽ chơi một hợp âm 3, 4 hoặc 5 nốt theo giọng của bài, bằng chuột, bàn phím máy tính hoặc bàn phím MIDI.","changelog.d9cada2e85a6":"<strong>Nốt bóng mờ.</strong> Khi bạn vẽ, nốt hoặc hợp âm tiếp theo được gợi ý mờ mờ; Tab giữ lại, một cú nhấp giữ một nốt, và vẽ ở chỗ khác sẽ xóa gợi ý.","changelog.01aa58d9ab50":"<strong>Lời bài hát.</strong> Gõ lời dưới giai điệu hoặc bè phụ, các âm tiết được đánh dấu: chúng được in lên bản nhạc và sáng lên khi được hát. Bộ đếm bên cạnh mỗi dòng cho biết dòng đó có vừa ô nhịp không. Khi bạn gõ, phần còn lại của từ được gợi ý (Tab để nhận) và lỗi chính tả được sửa, trừ khi bạn chạm dấu kiểm hoặc nhấn Shift+Tab để giữ từ của mình.","changelog.407e049442f6":"<strong>Bản thu, Mơ 1–3 và Mơ lại.</strong> Ba phiên bản mới của bất kỳ bè nào bên cạnh bản bạn đang có; chọn một và giữ lại. Mơ lại một bài cổ điển biến nó thành một bài hát mới của riêng bạn.","changelog.a2ae6ec40472":"<strong>Hạt giống.</strong> Mỗi lần tạo hiển thị hạt giống của nó và hạt giống bản thu của từng bè, kèm Sao chép. Dán hạt giống của một bài để tạo lại bài đó, hoặc hạt giống bản thu của một bè để lấy lại bản thu ấy.","changelog.7403cd98e6cb":"<strong>Lịch sử.</strong> Lùi và Tiến qua mọi lần tạo bạn đã làm, mỗi lần được đưa về chính xác và được giữ qua các lần khởi động lại. Một lần tạo mới không bao giờ lặp lại lần cũ.","changelog.3c500d42ebde":"<strong>Bài cổ điển là để học, không phải để lấy.</strong> Chỉ hợp âm của một bài cổ điển mới được đưa ra ngoài. Một bài được tạo có giai điệu, bè phụ hoặc bè trầm giống một giai điệu nổi tiếng sẽ giữ bè đó lại trong ứng dụng, và nói rõ lý do.","changelog.ce67fa868077":"<strong>Hộp thoại phím tắt.</strong> Nhấn ? hoặc nút của nó trên thanh trên cùng để xem mọi phím tắt.","changelog.4ca2136708d7":"<strong>Dự án của bạn ghi nhớ.</strong> Lưu dự án DAW sẽ giữ bài hát, các chỉnh sửa, bản mix, lời, đàn piano, góc nhìn và phần ghi công, và khi mở lại mọi thứ trở về như cũ.","changelog.2a6141e43be0":"Đã thay đổi","changelog.e60841228886":"<strong>Bản xem trước trên dòng thời gian lớn hơn</strong>, và hiển thị những lời đang được hát vào lúc đó.","changelog.1dca7b1d60db":"<span class=\"release__meta\"><span class=\"release__ver\">v0.3.0</span><time class=\"release__date\" datetime=\"2026-10-14\">2026-10-14</time></span>","changelog.d35d794c003e":"Đôi tay chân thực. Giờ đây một đôi tay chơi piano trên sân khấu của Handscore theo cách một nghệ sĩ piano sẽ chơi — mỗi ngón được chọn cho đoạn nhạc, ngón cái luồn xuống dưới khi chạy gam, một bàn tay nhấc lên vượt qua tay kia khi bản nhạc đòi hỏi bắt chéo tay. Sáu mươi hai bài kinh điển thuộc phạm vi công cộng đã sẵn sàng để học, từ Mary Had a Little Lamb đến Đêm thánh vô cùng và The Star-Spangled Banner, và thanh điều khiển phát bên dưới sân khấu cho phép bạn tạm dừng, tua lại, tua nhanh hoặc kéo đến bất kỳ thời điểm nào, nghe các nốt trong khi di chuyển.","changelog.0390e4a43a0a":"<strong>Đôi tay chân thực trên bàn phím.</strong> Hai bàn tay, kết thúc ở cổ tay, chơi mọi nốt trên cả bốn cây piano: mỗi ngón được chọn như một nghệ sĩ piano sẽ chọn, ngón cái luồn xuống dưới khi chạy gam, vươn tới những hợp âm rộng, ngón cái nằm nghiêng và hơi cong, và một bàn tay nhấc lên vượt qua tay kia để bắt chéo. Khi không có gì đang chơi, đôi tay đặt trên phím, sẵn sàng.","changelog.2c009dbabcfe":"<strong>Thế bấm ngón được tính trước khi một nốt vang lên.</strong> Handscore quyết định tay nào chơi mỗi nốt và bằng ngón nào trước khi nhạc vang lên, nên đôi tay đến đúng lúc phím đi xuống chứ không phải sau đó.","changelog.216f61cb53a3":"<strong>Chọn chế độ.</strong> Nút ở góc trên bên trái (hoặc P) giờ ghi <em>Chọn chế độ</em> và mở các lựa chọn của bạn theo danh mục: Nhạc cụ, Bài kinh điển, Đoạn nhạc và Bài học (sẽ có trong phiên bản sau).","changelog.44952a5f65fd":"<strong>Sáu mươi hai bài kinh điển để học.</strong> Bài hát thiếu nhi, nhạc Giáng sinh và thánh ca Giáng sinh, dân ca, nhạc spiritual và quốc ca, các chủ đề cổ điển và những bản piano được yêu thích — Chopsticks, Jingle Bells, Đêm thánh vô cùng, Ode to Joy, Für Elise, The Entertainer, The Star-Spangled Banner và nhiều bài khác — mỗi bài được soạn cho hai tay, giai điệu ở tay phải và hợp âm ở tay trái. Tìm chúng theo tên bài hoặc nhà soạn nhạc. Tất cả đều thuộc phạm vi công cộng.","changelog.d8fc29c977d3":"<strong>Đoạn nhạc để xem.</strong> Một gam, một ii–V–I, một hợp âm rải và một lần bắt chéo tay, mỗi đoạn là một cái nhìn nhanh vào đôi tay đang làm việc.","changelog.d0ff9a5e5f3f":"<strong>Thanh điều khiển phát.</strong> Phát, tạm dừng, dừng, tua lại và tua nhanh bên dưới sân khấu, với một dòng thời gian hiển thị thời gian của bài và các ô nhịp. Di chuột lên dòng thời gian để xem đôi tay tại thời điểm đó trong một bản xem trước nhỏ. Kéo dọc theo nó, hoặc nhấn giữ tua lại hay tua nhanh, và bạn nghe thấy mọi nốt bạn đi qua, theo cả hai chiều.","changelog.197a823169eb":"<strong>Máy đếm nhịp.</strong> Bật nó lên và một tiếng tích đánh dấu mỗi phách, phách đầu của mỗi ô nhịp cao hơn, trong khi các chấm bên cạnh chữ <em>M</em> của nó hiển thị phách.","changelog.f94e5b4b235f":"<strong>Phím cách để phát và tạm dừng.</strong>","changelog.dd397e7c80b2":"<strong>Nút nhạc cụ giờ là Chọn chế độ</strong>, và cây piano bạn chọn được đánh dấu <em>Hiện tại</em> trong Nhạc cụ.","changelog.c59c86e0cd28":"<span class=\"release__meta\"><span class=\"release__ver\">v0.2.0</span><time class=\"release__date\" datetime=\"2026-10-14\">2026-10-14</time></span>","changelog.14c84d5c455f":"Những cây piano thật. Giờ đây sân khấu của Handscore có bốn cây piano — một cây đại dương cầm biểu diễn, một cây đại dương cầm phòng khách, một cây piano đứng phòng thu và một cây piano đứng cũ kỹ từ quán rượu miền Viễn Tây — mỗi cây được chiếu sáng như trong phòng thu và mỗi cây có giọng riêng. Nhấp vào một phím hoặc chơi từ DAW của bạn và cây piano sẽ cất tiếng: phím đi xuống, tên của nó mờ dần, và pedal sustain giữ lại những nốt bạn buông ra. Bộ chọn piano cho phép bạn nghe một cây piano trước khi chọn nó.","changelog.a8f76e859570":"<strong>Bốn cây piano thật.</strong> Grand Piano, Acoustic Piano, Upright Piano và Honky-Tonk Piano, mỗi cây có hình dáng, lớp hoàn thiện và âm thanh riêng, ở cả hai giao diện.","changelog.6f544a8bd67f":"<strong>Chơi các phím.</strong> Nhấp vào một phím để nghe nó, hoặc lướt qua các phím để chơi lần lượt từng phím. MIDI từ DAW của bạn chơi cây piano và làm các phím của nó chuyển động, còn pedal sustain giữ những nốt bạn buông ra cho đến khi bạn nhấc chân khỏi pedal.","changelog.3f265130a08f":"<strong>Phím chuyển động như phím đàn piano.</strong> Mỗi phím đi xuống bằng cách xoay trên thanh cân bằng của nó, được chơi càng mạnh thì xuống càng nhanh, và tên của phím mờ đi khi phím đang xuống rồi hiện lại khi phím nâng lên.","changelog.7fd2c1ed940d":"<strong>Bộ chọn piano.</strong> Nút nhạc cụ ở góc trên bên trái (hoặc P) mở ra bốn thẻ. <em>Nghe thử</em> chơi một câu nhạc ngắn trên cây piano đó mà không đổi đàn; <em>Chọn</em> đưa nó lên sân khấu, chuyển tiếp mượt mà từ cây trước đó. Lựa chọn của bạn được lưu cùng dự án.","changelog.72aa386a33ff":"<strong>Chất lượng vừa với máy tính của bạn.</strong> Handscore đo xem máy tính của bạn vẽ sân khấu nhanh đến đâu và chọn mức chất lượng mà máy có thể duy trì mượt mà.","changelog.1246fc93bca0":"Đã sửa","changelog.58e041aeca75":"<strong>Phím theo kịp ngay cả trên máy tính đang bận.</strong> Một phím được chơi khi máy tính vẽ chậm có thể vẫn ở trên, hoặc tên của nó vẫn mờ một nửa; giờ đây phím luôn dừng đúng ở trạng thái mà cách chơi của bạn để lại.","changelog.e6eef73c000a":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-10-12\">2026-10-12</time></span>","changelog.ff94e0b1d59f":"Nền móng. Freally Handscore tải được dưới dạng plugin CLAP và VST3 lẫn ứng dụng độc lập, đề nghị bạn chấp nhận giấy phép, và mở ra trên sân khấu của nó: một bàn phím 88 phím theo đúng kích thước của một cây đàn piano thật, với tên của mọi phím ở mặt trước. Hiện chưa có gì được tạo ra — điều đó sẽ đến cùng những cây piano thật và đôi tay.","changelog.37cee751dc57":"<strong>Plugin và ứng dụng độc lập.</strong> CLAP và VST3 trên Windows (AU được dựng trên máy Mac), và một ứng dụng độc lập mang biểu tượng của Handscore trên thanh tiêu đề và thanh tác vụ.","changelog.bf0d03d43bfd":"<strong>Thỏa thuận cấp phép đến trước tiên.</strong> Cho đến khi bạn đồng ý, Handscore không làm gì. Câu trả lời của bạn được lưu trên máy tính của bạn và dùng chung cho mọi bản đang mở, trong mọi DAW và trong ứng dụng độc lập.","changelog.28bc52fb055e":"<strong>Sân khấu.</strong> Một bàn phím 88 phím, từ A0 đến C8, theo đúng kích thước của một cây đàn piano thật, trải kín chiều rộng cửa sổ. Tên của mỗi phím nằm ở mặt trước của nó — phím trắng in mực tối, phím đen in màu trắng — và ẩn đi khi phím đang được nhấn.","changelog.d51fdbedfc0e":"<strong>Sáng và tối.</strong> Công tắc ở góc trên bên phải; Handscore ghi nhớ lựa chọn của bạn.","changelog.9e0609310c1a":"<strong>Mười tám ngôn ngữ.</strong> Handscore khởi động bằng ngôn ngữ hệ thống của bạn.","changelog.f1cf7c9dfaa8":"<strong>Chế độ xem 3D biết báo khi không thể vẽ.</strong> Một cửa sổ không có WebGL 2 sẽ giải thích cách bật nó lên thay vì không hiển thị gì.","changelog.0fe089d138d3":"<strong>Sự cố được lưu lại, không bao giờ gửi đi.</strong> Nếu Handscore có lúc dừng đột ngột, một báo cáo ngắn sẽ được lưu trên máy tính của bạn cho lần khởi chạy tiếp theo. Không có gì rời khỏi máy tính của bạn trừ khi bạn chọn báo cáo sự cố."};
